match auth_state {
  = authenticated:
    match identity_group {
      = "guests":
        match protocol {
          = tcp:
            match dst_port {
              |(= 22 = 3389 = 445): verdict drop
            }
        }
    }
}

match auth_state {
  = authenticated:
    match identity_group {
      = "admins":
        match protocol {
          = tcp:
            match dst_port {
              |(= 443 = 8443): verdict allow
            }
        }
    }
}

match auth_state {
  = authenticated:
    match protocol {
      = tcp:
        match dst_port {
          |(= 80 = 443 = 8080): verdict allow
        }
      = icmp: verdict allow
    }
}
